// Package blobx is the object-storage abstraction used by the file module.
//
// It is a platform leaf package: no business types, no gin, no database. A
// Store moves bytes to and from an opaque key; the file domain owns metadata,
// ownership and permissions. Two drivers ship with the template:
//
//   - local: the filesystem, with HMAC-signed download URLs served by the app;
//   - s3: any S3-compatible endpoint (AWS S3, MinIO, Aliyun OSS, R2).
//
// Keys are generated by the caller (never derived from a user-supplied
// filename) and validated here so a driver can never be talked into escaping
// its root.
package blobx

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"
)

// Driver names. They are stored on every file row so switching backends does
// not orphan the objects written by the previous one.
const (
	// DriverLocal stores objects under a filesystem root.
	DriverLocal = "local"
	// DriverS3 stores objects through the S3 API.
	DriverS3 = "s3"
)

// Sentinel errors. Callers map them to business errors; drivers must wrap them
// (fmt.Errorf("...: %w", ErrNotFound)) instead of inventing their own.
var (
	// ErrNotFound means the object does not exist in the backend.
	ErrNotFound = errors.New("blobx: object not found")
	// ErrTooLarge means the object exceeds the configured upload limit.
	ErrTooLarge = errors.New("blobx: object exceeds the size limit")
	// ErrSizeMismatch means the bytes written do not match the declared size.
	ErrSizeMismatch = errors.New("blobx: written size does not match the declared size")
	// ErrInvalidKey means the key is empty, absolute or escapes the store root.
	ErrInvalidKey = errors.New("blobx: invalid object key")
)

// ObjectInfo describes one stored object.
type ObjectInfo struct {
	// Key is the storage key the object lives under.
	Key string
	// Size is the object size in bytes.
	Size int64
	// ContentType is what the driver recorded (or what the caller declared).
	ContentType string
	// ModTime is the last modification time reported by the backend.
	ModTime time.Time
}

// SignedURLOptions tunes a download URL.
type SignedURLOptions struct {
	// Expiry bounds the URL lifetime. Drivers clamp it to their own maximum
	// (SigV4: 7 days) and to a sane minimum.
	Expiry time.Duration
	// Disposition is "inline" or "attachment". Only types on the inline
	// allowlist may be inline; that decision belongs to the file service.
	Disposition string
	// Filename is the download name echoed by drivers that can set it
	// (S3 response-content-disposition).
	Filename string
	// ContentType is the content type the driver should pin on the response
	// (S3 response-content-type). Empty means "use the stored object metadata".
	ContentType string
	// PathID is a caller-owned opaque segment a driver may embed in the URL path
	// so the app can resolve the object without exposing the storage key
	// (local driver: the file id).
	PathID string
}

// Store is the driver contract. Implementations must be safe for concurrent use
// and must honor ctx for cancellation (S3 requests) or leave a fast filesystem
// call as-is.
type Store interface {
	// Driver reports the driver name stored on file rows.
	Driver() string
	// Put writes size bytes from body under key. It must not read more than size
	// bytes and must return ErrSizeMismatch when the stream ends early.
	Put(ctx context.Context, key string, body io.Reader, size int64, contentType string) (ObjectInfo, error)
	// Open returns the object content and its metadata.
	Open(ctx context.Context, key string) (io.ReadCloser, ObjectInfo, error)
	// Stat returns metadata without opening the object.
	Stat(ctx context.Context, key string) (ObjectInfo, error)
	// Delete removes the object. Deleting a missing object is not an error:
	// purge jobs must be idempotent.
	Delete(ctx context.Context, key string) error
	// URL returns a browser-usable download URL and its expiry.
	URL(ctx context.Context, key string, opt SignedURLOptions) (string, time.Time, error)
}

// ValidateKey rejects keys that are empty, absolute, contain a backslash or a
// ".." segment. Drivers call it; callers generate keys like
// "file/202601/4f1c....png".
func ValidateKey(key string) error {
	switch {
	case key == "":
		return fmt.Errorf("%w: empty", ErrInvalidKey)
	case len(key) > 1024:
		return fmt.Errorf("%w: too long", ErrInvalidKey)
	case strings.HasPrefix(key, "/"):
		return fmt.Errorf("%w: absolute path", ErrInvalidKey)
	case strings.Contains(key, "\\"):
		return fmt.Errorf("%w: backslash", ErrInvalidKey)
	}
	for _, segment := range strings.Split(key, "/") {
		if segment == "" || segment == "." || segment == ".." {
			return fmt.Errorf("%w: bad segment", ErrInvalidKey)
		}
	}
	for _, r := range key {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("%w: control character", ErrInvalidKey)
		}
	}
	return nil
}

// clampExpiry bounds a requested lifetime to [10s, 7d].
func clampExpiry(expiry, fallback time.Duration) time.Duration {
	if expiry <= 0 {
		expiry = fallback
	}
	if expiry < 10*time.Second {
		expiry = 10 * time.Second
	}
	if expiry > 7*24*time.Hour {
		expiry = 7 * 24 * time.Hour
	}
	return expiry
}
